// Stamps the canonical generated-file banner onto the TypeScript client.
//
// @hey-api/openapi-ts writes its own provenance line but no DO NOT EDIT
// marker, so its output was the one generated surface a reader could open
// without being told to leave it alone — and the one the manifest could not
// check the same way as every other artifact.
//
// This runs as a step of the generation pipeline, immediately after the
// generator, so the stamped file is still purely a function of the schema plus
// the generator. It is idempotent: re-stamping an already-stamped file is a
// no-op, which is what keeps the drift lock quiet across repeated runs.

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const CLIENT_DIR = new URL('../../apps/webui/src/client-ts/', import.meta.url).pathname;
const BANNER = '// Code generated by @hey-api/openapi-ts from backend/api/openapi.yaml; DO NOT EDIT.';

let stamped = 0;
for (const entry of readdirSync(CLIENT_DIR, { recursive: true, withFileTypes: true })) {
  if (!entry.isFile()) continue;
  if (entry.name.startsWith('._')) continue;

  const path = join(entry.parentPath ?? entry.path, entry.name);
  const source = readFileSync(path, 'utf8');
  if (source.startsWith(BANNER)) continue;

  writeFileSync(path, `${BANNER}\n${source}`, 'utf8');
  stamped += 1;
}

console.log(`stamp-client-ts-marker: stamped ${stamped} file(s)`);
